/**
 * @param {import('gorules').Input} input
 * input: { documentCount, flagCount, claimAmount, autoApproveMaxAmount }
 */
const handler = (input) => {
  if (input.documentCount === 0) {
    return { status: 'AUTO_REJECTED', reason: 'No documents submitted' };
  }

  if (input.flagCount === 0 && input.claimAmount < input.autoApproveMaxAmount) {
    return { status: 'AUTO_APPROVED', reason: 'Rules passed, no validation flags, low value' };
  }

  return { status: 'UNDER_REVIEW', reason: 'Validation flags present or high value - needs adjuster review' };
};
